void sleepScreen(void) {
    u8g2.setPowerSave(0);
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    u8g2.drawXBMP(57, 24, 15, 16, sleepBits);
    u8g2.setDrawColor(2);
    u8g2.sendBuffer();
    delay(1000);
}

int backDelay = 100;
int backTime = 0;

void loop(void)
{
    resetButtonStates();

    if(anyButtonHold()){
        afkTime = 0; 
    } else {
        afkTime += 1; 
    }

    if(afkTime >= maxAfkTime){
        sleepScreen();
        btStop();
        #if CONFIG_IDF_TARGET_ESP32
            // Classic ESP32
            esp_sleep_enable_ext0_wakeup((gpio_num_t)33, 0);
            
        #elif CONFIG_IDF_TARGET_ESP32C3
            // ESP32-C3
            gpio_wakeup_enable((gpio_num_t)9, GPIO_INTR_LOW_LEVEL);
            esp_sleep_enable_gpio_wakeup();
        #endif
        u8g2.setPowerSave(1);
        delay(50);
        while (digitalRead(leftButton) == LOW) {
            delay(10);
        }
        wokefromSleep = 1;
        esp_deep_sleep_start();
        return;
    }

    switch (currentScene)
    {
        case 0:
            mainMenu(); // display the main menu
            if (upButtonTap())
            {
                previousItem(); // if the previous button is pressed, go to the previous item
            }
            if (selectButtonTap())
            {
                currentScene = currentItemIndex; // set the current scene to the selected item index
            }
            if (downButtonTap())
            {
                nextItem(); // if the next button is pressed, go to the next item
            }
        break;
            
        case 1:
            compass(!leftButtonHold() && !rightButtonHold() ? 0 : (!leftButtonHold() && rightButtonHold() ? -1 : 1), downButtonTap()); // display the compass

            if (selectButtonTap())
            {
                currentScene = 0; // if the select button is pressed, go back to the main menu
            }
        break;;
    
        case 2:
            snakeGame(upButtonTap(), downButtonTap(), leftButtonTap(), rightButtonTap()); // display the snake game
            if (selectButtonTap())
            {
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;
    
        case 3:
            if (rightButtonHold())
            {
                backTime += 1;
                if(backTime > backDelay){

                    backTime = 0;
                    currentScene = 0;        // if the select button is pressed, go back to the main menu
                    return;
                }
            }else{
                backTime = 0;
            }
            ButtonTest(backTime, backDelay);
        break;;
    
        case 4:
            PC_Control();
            if (selectButtonTap())
            {
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 5:
            settingsPage();
            if (selectButtonTap())
            {
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 6:
            clockFunc(0);
            if (selectButtonTap())
            {   
                if(clockMode != NONE){
                    clockMode = NONE;
                    return;
                }
                clockFunc(1);
                gotInfo = 0;
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 7:
            gamesMenu(0);
            if(selectButtonTap()){
                gamesMenu(1);
                currentScene = 0;
            }
        break;

    }
}

